 63→// Build reverse lookup: synonym -> canonical
 64→const synonymToCanonical = new Map<string, string>();
 65→for (const [canonical, synonyms] of Object.entries(SKILL_SYNONYMS)) {
 66→  synonymToCanonical.set(canonical, canonical);
 67→  for (const syn of synonyms) {
 68→    synonymToCanonical.set(syn, canonical);
 69→  }
 70→}
 71→
 72→function normalizeSkill(skill: string): string {
 73→  const lower = skill.toLowerCase().trim()
 74→    .replace(/[.\-\/]/g, '')  // remove dots, hyphens, slashes for comparison
 75→    .replace(/\s+/g, ' ');    // normalize whitespace
 76→  return synonymToCanonical.get(lower) || synonymToCanonical.get(skill.toLowerCase().trim()) || lower;
 77→}
 78→
 79→function tokenize(term: string): string[] {
 80→  return term.toLowerCase().replace(/[^a-z0-9\s+#]/g, ' ').split(/\s+/).filter(t => t.length > 1);
 81→}
 82→
 83→function tokenOverlap(a: string, b: string): number {
 84→  const tokensA = tokenize(a);
 85→  const tokensB = tokenize(b);
 86→  if (tokensA.length === 0 || tokensB.length === 0) return 0;
 87→  const setB = new Set(tokensB);
 88→  const matched = tokensA.filter(t => setB.has(t)).length;
 89→  return matched / Math.max(tokensA.length, tokensB.length);
 90→}
 91→
 92→function fuzzyMatch(jdTerm: string, resumeTerms: string[]): boolean {
 93→  const normalizedJd = normalizeSkill(jdTerm);
 94→  for (const rt of resumeTerms) {
 95→    const normalizedResume = normalizeSkill(rt);
 96→    // Exact match after normalization
 97→    if (normalizedJd === normalizedResume) return true;
 98→    // Substring containment (original behavior)
 99→    if (normalizedJd.includes(normalizedResume) || normalizedResume.includes(normalizedJd)) return true;
100→    // Token overlap (e.g. "machine learning" vs "ml engineering" after synonym expansion)
101→    if (tokenOverlap(normalizedJd, normalizedResume) >= 0.5) return true;
102→  }
103→  return false;
104→}
105→
106→function extractResumeTerms(parsedJson: any): string[] {
107→  const p = parsedJson || {};
108→  const resumeSkills = (p.skills_with_evidence || []).map((s: any) =>
109→    (typeof s === 'string' ? s : s.skill || s.name || '').toLowerCase()
110→  );
111→  const resumeTools = (p.tools || []).map((t: string) => t.toLowerCase());
112→  // Also include domain experience and role titles for broader matching
113→  const domains = p.domain_experience ? [p.domain_experience.toLowerCase()] : [];
114→  const roleTitles = (p.roles_with_dates || []).map((r: any) => (r.title || r.role || '').toLowerCase());
115→  return [...resumeSkills, ...resumeTools, ...domains, ...roleTitles].filter(Boolean);
116→}
