118→serve(async (req) => {
119→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
120→
121→  try {
122→    const authHeader = req.headers.get("Authorization");
123→    if (!authHeader) throw new Error("No auth header");
124→
125→    const token = authHeader.replace("Bearer ", "");
126→    const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
127→    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
128→      global: { headers: { Authorization: authHeader } },
129→    });
130→    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
131→    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
132→    const user = { id: claimsData.claims.sub as string };
133→
134→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
135→
136→    // Fetch ranking config
137→    const { data: rankingConfig } = await supabase.from("ranking_config").select("*").limit(1).single();
138→    const cfg = {
139→      model: rankingConfig?.model || "gpt-4o-mini",
140→      temperature: rankingConfig?.temperature ?? 0.2,
141→      max_resume_chars: rankingConfig?.max_resume_chars ?? 4000,
142→      num_interview_questions: rankingConfig?.num_interview_questions ?? 5,
143→    };
144→    const resumeParsePrompt: string | null = rankingConfig?.resume_parse_prompt || null;
145→    const deepScoringPrompt: string | null = rankingConfig?.deep_scoring_prompt || null;
146→
147→    const { job_id, resume_ids } = await req.json();
148→    if (!job_id) throw new Error("Missing job_id");
149→
150→    // Rate limit: 3 jobs/min
151→    const oneMinAgo = new Date(Date.now() - 60000).toISOString();
152→    const { count } = await supabase
153→      .from("jobs")
154→      .select("id", { count: "exact", head: true })
155→      .eq("user_id", user.id)
156→      .gte("created_at", oneMinAgo);
157→    if ((count ?? 0) > 3) {
158→      return new Response(JSON.stringify({ error: "Rate limit: max 3 jobs per minute" }), {
159→        status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" },
160→      });
161→    }
162→
163→    // Fetch job with JD analysis
164→    const { data: job } = await supabase.from("jobs").select("*").eq("id", job_id).single();
165→    if (!job) throw new Error("Job not found");
166→    if (job.user_id !== user.id) throw new Error("Unauthorized");
167→
168→    const jdAnalysis = job.jd_analysis_json;
169→    const dynamicWeights = job.dynamic_weights_json;
170→    const jdEmbedding = job.jd_embedding;
171→
172→    if (!jdAnalysis || !dynamicWeights) {
173→      return new Response(
174→        JSON.stringify({ error: "JD analysis required. Please analyze the job description first." }),
175→        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
176→      );
177→    }
178→
179→    // Determine which resumes to process
180→    let targetResumeIds: string[] = resume_ids || [];
181→    if (!targetResumeIds.length) {
182→      const { data: allResumes } = await supabase
183→        .from("resumes")
184→        .select("id")
185→        .eq("job_id", job_id);
186→      targetResumeIds = (allResumes || []).map((r: any) => r.id);
187→    }
188→
189→    if (targetResumeIds.length === 0) {
190→      return new Response(JSON.stringify({ error: "No resumes to rank" }), {
191→        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
192→      });
193→    }
194→
195→    // Deduct credits (charge for min of resume count and 20)
196→    const creditsToCharge = Math.min(targetResumeIds.length, 20);
197→    const { data: creditOk } = await supabase.rpc("deduct_credits", {
198→      _user_id: user.id, _job_id: job_id, _amount: creditsToCharge,
199→    });
200→    if (!creditOk) {
201→      await supabase.from("jobs").update({ status: "failed" }).eq("id", job_id);
202→      return new Response(JSON.stringify({ error: "Insufficient credits" }), {
203→        status: 402, headers: { ...corsHeaders, "Content-Type": "application/json" },
204→      });
205→    }
206→
207→    // Mark job as processing
208→    await supabase.from("jobs").update({
209→      status: "processing",
210→      processing_started_at: new Date().toISOString(),
211→    }).eq("id", job_id);
212→
213→    // ─── STEP 1: Parse resumes (cached) ───────────────────────────
214→    console.log(`Parsing ${targetResumeIds.length} resumes...`);
215→    for (const rid of targetResumeIds) {
216→      await supabase.from("resumes").update({ status: "processing" }).eq("id", rid);
217→
218→      const { data: resume } = await supabase.from("resumes").select("*").eq("id", rid).single();
219→      if (!resume) continue;
220→
221→      // Skip if already parsed with current version
222→      if (resume.parsed_json && resume.parse_version === CURRENT_PARSE_VERSION) {
223→        continue;
224→      }
225→
226→      // Extract raw text
227→      let rawText = resume.parsed_text;
228→      if (!rawText && resume.file_path) {
229→        const { data: fileData } = await supabase.storage.from("resumes").download(resume.file_path);
230→        if (fileData) {
231→          const buffer = await fileData.arrayBuffer();
232→          if (resume.filename.toLowerCase().endsWith(".pdf")) {
233→            try {
234→              const result = await extractText(buffer);
235→              rawText = Array.isArray(result.text) ? result.text.join("\n") : String(result.text || "");
236→              rawText = rawText.slice(0, 10000);
237→            } catch {
238→              rawText = extractPdfText(new Uint8Array(buffer));
239→            }
240→          } else {
241→            rawText = new TextDecoder("utf-8", { fatal: false }).decode(buffer).slice(0, 10000);
242→          }
243→          await supabase.from("resumes").update({ parsed_text: rawText }).eq("id", rid);
244→        }
245→      }
246→
247→      if (!rawText) {
248→        await supabase.from("resumes").update({ status: "failed" }).eq("id", rid);
249→        continue;
250→      }
251→
252→      // LLM parse call for structured JSON
253→      try {
254→        const parsed = await parseResumeWithLLM(rawText, cfg, resumeParsePrompt);
255→        await supabase.from("resumes").update({
256→          parsed_json: parsed,
257→          parse_version: CURRENT_PARSE_VERSION,
258→          parsed_at: new Date().toISOString(),
259→          candidate_name: parsed.candidate_name || resume.candidate_name,
260→        } as any).eq("id", rid);
261→      } catch (err) {
262→        console.error(`Failed to parse resume ${rid}:`, err);
263→        await supabase.from("resumes").update({ status: "failed" }).eq("id", rid);
264→      }
265→    }
266→
267→    // ─── STEP 2: Generate embeddings (cached) ─────────────────────
268→    console.log("Generating embeddings...");
269→    const { data: resumesForEmbedding } = await supabase
270→      .from("resumes")
271→      .select("id, parsed_json, embedding, parsed_text")
272→      .in("id", targetResumeIds);
273→
274→    const needEmbedding = (resumesForEmbedding || []).filter((r: any) => !r.embedding && (r.parsed_json || r.parsed_text));
275→    if (needEmbedding.length > 0) {
276→      // Build summaries for embedding (from parsed_json to reduce injection)
277→      const summaries = needEmbedding.map((r: any) => {
278→        if (r.parsed_json) {
279→          const p = r.parsed_json;
280→          const parts: string[] = [];
281→          if (p.candidate_name) parts.push(p.candidate_name);
282→          if (p.skills_with_evidence) parts.push(`Skills: ${p.skills_with_evidence.map((s: any) => typeof s === 'string' ? s : s.skill || s.name || '').join(', ')}`);
283→          if (p.tools) parts.push(`Tools: ${p.tools.join(', ')}`);
284→          if (p.domain_experience) parts.push(`Domain: ${p.domain_experience}`);
285→          if (p.roles_with_dates) parts.push(`Roles: ${p.roles_with_dates.map((r: any) => `${r.title || r.role || ''} at ${r.company || ''}`).join('; ')}`);
286→          if (p.education) parts.push(`Education: ${p.education.map((e: any) => typeof e === 'string' ? e : `${e.degree || ''} ${e.institution || ''}`).join('; ')}`);
287→          return parts.join('. ').slice(0, 4000);
288→        }
289→        return (r.parsed_text || '').slice(0, 4000);
290→      });
291→
292→      // Batch embedding call
293→      const embResponse = await fetch("https://api.openai.com/v1/embeddings", {
294→        method: "POST",
295→        headers: { Authorization: `Bearer ${OPENAI_API_KEY}`, "Content-Type": "application/json" },
296→        body: JSON.stringify({ model: "text-embedding-3-small", input: summaries }),
297→      });
298→
299→      if (embResponse.ok) {
300→        const embData = await embResponse.json();
301→        for (let i = 0; i < needEmbedding.length; i++) {
302→          const embedding = embData.data?.[i]?.embedding;
303→          if (embedding) {
304→            await supabase.from("resumes").update({
305→              embedding: JSON.stringify(embedding),
306→            } as any).eq("id", needEmbedding[i].id);
307→          }
308→        }
309→      }
310→    }
311→
312→    // ─── STEP 3: Shortlist top 50 via pgvector ────────────────────
313→    let shortlistedIds: string[] = targetResumeIds;
314→
315→    if (jdEmbedding && targetResumeIds.length > 50) {
316→      console.log("Shortlisting top 50 via embedding similarity...");
317→      const { data: similar } = await supabase.rpc("match_resumes_by_embedding", {
318→        query_embedding: jdEmbedding,
319→        match_job_id: job_id,
320→        match_count: 50,
321→      });
322→      if (similar && similar.length > 0) {
323→        shortlistedIds = similar.map((s: any) => s.id);
324→      }
325→    }
326→
327→    // ─── STEP 4: Heuristic rerank to top 20 ──────────────────────
328→    let top20Ids = shortlistedIds;
329→    if (shortlistedIds.length > 20) {
330→      console.log("Heuristic reranking to top 20...");
331→      const { data: shortlistedResumes } = await supabase
332→        .from("resumes")
333→        .select("id, parsed_json")
334→        .in("id", shortlistedIds);
335→
336→      if (shortlistedResumes) {
337→        const scored = shortlistedResumes.map((r: any) => {
338→          let score = 0;
339→          const mustHaves = jdAnalysis.critical_must_haves || [];
340→          const tools = jdAnalysis.tools || [];
341→          const allResumeTerms = extractResumeTerms(r.parsed_json);
342→
343→          for (const mh of mustHaves) {
344→            if (fuzzyMatch(mh, allResumeTerms)) score += 3;
345→          }
346→          for (const tool of tools) {
347→            if (fuzzyMatch(tool, allResumeTerms)) score += 1;
348→          }
349→
350→          // Preferred must-haves (lower weight)
351→          const preferred = jdAnalysis.preferred_must_haves || [];
352→          for (const pref of preferred) {
353→            if (fuzzyMatch(pref, allResumeTerms)) score += 1.5;
354→          }
355→
356→          // Years estimate
357→          const roles = (r.parsed_json || {}).roles_with_dates || [];
358→          if (roles.length > 0) score += Math.min(roles.length, 5);
359→
360→          return { id: r.id, score };
361→        });
362→
363→        scored.sort((a, b) => b.score - a.score);
364→        top20Ids = scored.slice(0, 20).map((s) => s.id);
365→      }
366→    }
367→
368→    // ─── STEP 5: Deep score top 20 ───────────────────────────────
369→    console.log(`Deep scoring ${top20Ids.length} resumes...`);
370→    const dimensions = jdAnalysis.evaluation_dimensions || [];
371→    let successCount = 0;
372→    let failCount = 0;
373→
374→    // Process in parallel batches of 5
375→    const batchSize = 5;
376→    for (let i = 0; i < top20Ids.length; i += batchSize) {
377→      const batch = top20Ids.slice(i, i + batchSize);
378→      const promises = batch.map(async (rid) => {
379→        const { data: resume } = await supabase
380→          .from("resumes")
381→          .select("id, filename, parsed_json, parsed_text, candidate_name")
382→          .eq("id", rid)
383→          .single();
384→        if (!resume) return;
385→
386→        try {
387→          const resumeText = resume.parsed_text || JSON.stringify(resume.parsed_json || {});
388→          const deepResult = await deepScoreResume(
389→            job.job_description,
390→            resumeText,
391→            resume.parsed_json,
392→            jdAnalysis,
393→            dimensions,
394→            cfg,
395→            deepScoringPrompt
396→          );
397→
398→          // Compute overall score deterministically
399→          let overallScore = 0;
400→          const categoryScores = deepResult.category_scores || {};
401→          for (const dim of dimensions) {
402→            const dimScore = categoryScores[dim.key]?.score ?? 0;
403→            const weight = dynamicWeights[dim.key] ?? 0;
404→            overallScore += dimScore * weight;
405→          }
406→          overallScore = Math.round(overallScore * 100) / 100;
407→
408→          // Hard fit cap
409→          let hardFit = deepResult.hard_fit !== false;
410→          const missingCritical = deepResult.missing_critical_must_haves || [];
411→          if (missingCritical.length > 0) {
412→            hardFit = false;
413→            overallScore = Math.min(overallScore, 49);
414→          }
415→
416→          // Update candidate name
417→          if (deepResult.candidate_name && deepResult.candidate_name !== "Unknown Candidate") {
418→            await supabase.from("resumes").update({
419→              candidate_name: deepResult.candidate_name,
420→              status: "done",
421→            }).eq("id", rid);
422→          } else {
423→            await supabase.from("resumes").update({ status: "done" }).eq("id", rid);
424→          }
425→
426→          // Upsert result
427→          // Check if result exists for this resume
428→          const { data: existingResult } = await supabase
429→            .from("results")
430→            .select("id")
431→            .eq("resume_id", rid)
432→            .limit(1)
433→            .maybeSingle();
434→
435→          const resultData = {
436→            resume_id: rid,
437→            job_id: job_id,
438→            scoring_version: CURRENT_PARSE_VERSION,
439→            overall_score: overallScore,
440→            hard_fit: hardFit,
441→            confidence: deepResult.confidence ?? 0,
442→            category_scores_json: categoryScores,
443→            strengths_json: deepResult.strengths || [],
444→            gaps_json: deepResult.gaps || [],
445→            interview_questions: deepResult.interview_questions || [],
446→            explanation_json: deepResult.explanation || {},
447→            matched_must_haves: deepResult.matched_critical_must_haves || [],
448→            missing_must_haves: missingCritical,
449→            missing_skills: missingCritical,
450→            summary: deepResult.explanation?.summary || "",
451→            // Keep old columns null for new scoring
452→            skill_score: null,
453→            experience_score: null,
454→            education_score: null,
455→          };
456→
457→          if (existingResult) {
458→            await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
459→          } else {
460→            await supabase.from("results").insert(resultData as any);
461→          }
462→
463→          successCount++;
464→          console.log(`Resume ${rid} scored: overall=${overallScore}, hardFit=${hardFit}`);
465→        } catch (err) {
466→          failCount++;
467→          console.error(`Error scoring resume ${rid}:`, err);
468→          await supabase.from("resumes").update({ status: "failed" }).eq("id", rid);
469→          // Insert failed result (wrapped to prevent crash propagation)
470→          try {
471→            const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", rid).limit(1).maybeSingle();
472→            if (!existingResult) {
473→              await supabase.from("results").insert({
474→                resume_id: rid,
475→                job_id: job_id,
476→                overall_score: 0,
477→                hard_fit: false,
478→                confidence: 0,
479→                category_scores_json: {},
480→                strengths_json: [],
481→                gaps_json: [],
482→                summary: `Scoring failed: ${err instanceof Error ? err.message : "Unknown error"}`,
483→              } as any);
484→            }
485→          } catch (insertErr) {
486→            console.error(`Failed to insert error result for ${rid}:`, insertErr);
487→          }
488→        }
489→      });
490→
491→      await Promise.all(promises);
492→    }
493→
494→    // ─── STEP 6: Heuristic score remaining resumes ─────────────
495→    const unscoredIds = targetResumeIds.filter((id) => !top20Ids.includes(id));
496→    if (unscoredIds.length > 0) {
497→      console.log(`Heuristic scoring ${unscoredIds.length} remaining resumes...`);
498→
499→      // Get all similarity scores (covering all resumes, not just top 50)
500→      let similarityMap = new Map<string, number>();
501→      if (jdEmbedding) {
502→        const { data: allSimilar } = await supabase.rpc("match_resumes_by_embedding", {
503→          query_embedding: jdEmbedding,
504→          match_job_id: job_id,
505→          match_count: targetResumeIds.length,
506→        });
507→        if (allSimilar) {
508→          for (const s of allSimilar) {
509→            similarityMap.set(s.id, s.similarity);
510→          }
511→        }
512→      }
513→
514→      // Fetch parsed data for unscored resumes
515→      const { data: unscoredResumes } = await supabase
516→        .from("resumes")
517→        .select("id, parsed_json, candidate_name")
518→        .in("id", unscoredIds);
519→
520→      const mustHaves = jdAnalysis.critical_must_haves || [];
521→      const jdTools = jdAnalysis.tools || [];
522→
523→      for (const resume of (unscoredResumes || [])) {
524→        const allResumeTerms = extractResumeTerms(resume.parsed_json);
525→
526→        // Keyword overlap score (0-100)
527→        const totalKeywords = mustHaves.length + jdTools.length;
