791→// ── PDF text extraction fallback ───────────────────────────────
792→function extractPdfText(bytes: Uint8Array): string {
793→  const raw = new TextDecoder("latin1").decode(bytes);
794→  const textChunks: string[] = [];
795→  const btEtRegex = /BT\s([\s\S]*?)ET/g;
796→  let block;
797→  while ((block = btEtRegex.exec(raw)) !== null) {
798→    const parenRegex = /\(([^)]*)\)/g;
799→    let match;
800→    while ((match = parenRegex.exec(block[1])) !== null) {
801→      const decoded = match[1]
802→        .replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t")
803→        .replace(/\\\\/g, "\\").replace(/\\\(/g, "(").replace(/\\\)/g, ")");
804→      if (decoded.trim()) textChunks.push(decoded);
805→    }
806→  }
807→  if (textChunks.join(" ").trim().length < 200) {
808→    const streamRegex = /stream\r?\n([\s\S]*?)\r?\nendstream/g;
809→    let sm;
810→    while ((sm = streamRegex.exec(raw)) !== null) {
811→      const readable = sm[1].replace(/[^\x20-\x7E\n\r\t]/g, " ").replace(/\s+/g, " ").trim();
812→      if (readable.length > 50) textChunks.push(readable);
813→    }
814→  }
815→  return textChunks.join(" ").replace(/\s+/g, " ").trim().slice(0, 10000);
816→}
